insert into public.curriculum_quiz_questions
(id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,validation_status,is_published,question_type,accepted_answers,image_url,metadata)
values
('10000003-71a0-4d01-9013-000000000001'::uuid,'53a21b23-f81b-4ffe-b014-83560d34e919'::uuid,'Quel est l’ordre d’organisation du plus simple au plus complexe ?','Le corps humain s’organise des cellules vers les tissus, puis les organes et enfin les systèmes.','[{"text":"Cellule → tissu → organe → système","correct":true},{"text":"Système → organe → tissu → cellule","correct":false},{"text":"Tissu → système → cellule → organe","correct":false},{"text":"Organe → cellule → système → tissu","correct":false}]'::jsonb,1,'NIH/NCI SEER — Introduction to the Human Body',901,'source_validated',true,'mcq','[]'::jsonb,null,'{"source_url":"https://training.seer.cancer.gov/anatomy/body/review.html","source_validation":"institutional_validated"}'::jsonb),
('10000003-71a0-4d01-9013-000000000002'::uuid,'53a21b23-f81b-4ffe-b014-83560d34e919'::uuid,'Qu’est-ce qu’un organe ?','Un organe associe plusieurs types de tissus organisés pour accomplir une fonction particulière.','[{"text":"Un ensemble de tissus organisés pour une fonction","correct":true},{"text":"Une seule molécule","correct":false},{"text":"Un groupe de systèmes","correct":false},{"text":"Une seule cellule isolée","correct":false}]'::jsonb,1,'NIH/NCI SEER — Introduction to the Human Body',902,'source_validated',true,'mcq','[]'::jsonb,null,'{"source_url":"https://training.seer.cancer.gov/anatomy/body/review.html","source_validation":"institutional_validated"}'::jsonb),
('10000003-71a0-4d01-9013-000000000003'::uuid,'53a21b23-f81b-4ffe-b014-83560d34e919'::uuid,'Qu’est-ce qu’un système anatomique ?','Un système associe plusieurs organes qui coopèrent pour réaliser des fonctions complexes de l’organisme.','[{"text":"Un ensemble d’organes coopérant pour des fonctions complexes","correct":true},{"text":"Une seule cellule spécialisée","correct":false},{"text":"Une protéine structurale","correct":false},{"text":"Un seul tissu sans organe","correct":false}]'::jsonb,2,'NIH/NCI SEER — Introduction to the Human Body',903,'source_validated',true,'mcq','[]'::jsonb,null,'{"source_url":"https://training.seer.cancer.gov/anatomy/body/review.html","source_validation":"institutional_validated"}'::jsonb),
('10000003-71a0-4d01-9013-000000000004'::uuid,'53a21b23-f81b-4ffe-b014-83560d34e919'::uuid,'Lequel appartient aux grands systèmes du corps humain ?','Le système nerveux figure parmi les grands systèmes décrits dans l’organisation anatomique du corps humain.','[{"text":"Le système nerveux","correct":true},{"text":"Le système alphabétique","correct":false},{"text":"Le système métrique","correct":false},{"text":"Le système monétaire","correct":false}]'::jsonb,2,'NIH/NCI SEER — Anatomy & Physiology',904,'source_validated',true,'mcq','[]'::jsonb,null,'{"source_url":"https://training.seer.cancer.gov/anatomy/","source_validation":"institutional_validated"}'::jsonb),
('10000003-71a0-4d01-9013-000000000005'::uuid,'53a21b23-f81b-4ffe-b014-83560d34e919'::uuid,'À quoi servent les termes directionnels en anatomie ?','Ils permettent de décrire précisément la position relative de structures corporelles.','[{"text":"À préciser la position relative des structures","correct":true},{"text":"À mesurer uniquement la glycémie","correct":false},{"text":"À classer les groupes sanguins","correct":false},{"text":"À déterminer uniquement le rythme cardiaque","correct":false}]'::jsonb,2,'NIH/NCI SEER — Introduction to the Human Body',905,'source_validated',true,'mcq','[]'::jsonb,null,'{"source_url":"https://training.seer.cancer.gov/anatomy/body/review.html","source_validation":"institutional_validated"}'::jsonb),
('10000003-71a0-4d01-9013-000000000006'::uuid,'53a21b23-f81b-4ffe-b014-83560d34e919'::uuid,'Pourquoi utilise-t-on des plans anatomiques de référence ?','Les plans anatomiques permettent de décrire de façon standardisée des sections, positions et relations dans le corps.','[{"text":"Pour décrire le corps selon des repères standardisés","correct":true},{"text":"Pour classer les médicaments","correct":false},{"text":"Pour déterminer le groupe ABO","correct":false},{"text":"Pour mesurer la coagulation","correct":false}]'::jsonb,3,'NIH/NCI SEER — Introduction to the Human Body',906,'source_validated',true,'mcq','[]'::jsonb,null,'{"source_url":"https://training.seer.cancer.gov/anatomy/body/review.html","source_validation":"institutional_validated"}'::jsonb),
('10000003-71a0-4d01-9013-000000000007'::uuid,'53a21b23-f81b-4ffe-b014-83560d34e919'::uuid,'Que désigne l’homéostasie ?','L’homéostasie correspond au maintien ou au rétablissement d’une relative stabilité de l’environnement interne.','[{"text":"Le maintien relatif de la stabilité du milieu intérieur","correct":true},{"text":"L’arrêt de toute variation physiologique","correct":false},{"text":"La destruction des tissus vieillissants uniquement","correct":false},{"text":"La production de toutes les hormones","correct":false}]'::jsonb,3,'NIH/NCI SEER — Introduction to the Human Body',907,'source_validated',true,'mcq','[]'::jsonb,null,'{"source_url":"https://training.seer.cancer.gov/anatomy/body/review.html","source_validation":"institutional_validated"}'::jsonb),
('10000003-71a0-4d01-9013-000000000008'::uuid,'53a21b23-f81b-4ffe-b014-83560d34e919'::uuid,'Cas d’application — Une pathologie atteint plusieurs tissus différents réunis dans une même structure fonctionnelle. Quel niveau d’organisation est directement concerné ?','Une structure formée de plusieurs tissus différents organisés pour une fonction correspond à un organe.','[{"text":"Un organe","correct":true},{"text":"Un nucléotide","correct":false},{"text":"Un allèle","correct":false},{"text":"Un ion","correct":false}]'::jsonb,4,'NIH/NCI SEER — Introduction to the Human Body',908,'source_validated',true,'clinical_case','[]'::jsonb,null,'{"source_url":"https://training.seer.cancer.gov/anatomy/body/review.html","source_validation":"institutional_validated"}'::jsonb),
('10000003-71a0-4d01-9013-000000000009'::uuid,'53a21b23-f81b-4ffe-b014-83560d34e919'::uuid,'Quel raisonnement résume le mieux l’organisation anatomique du corps humain ?','Les cellules s’organisent en tissus, les tissus en organes et les organes en systèmes interdépendants qui contribuent au maintien de l’organisme.','[{"text":"Une organisation hiérarchique de cellules à systèmes interdépendants","correct":true},{"text":"Des organes sans tissus","correct":false},{"text":"Des systèmes constitués uniquement de molécules isolées","correct":false},{"text":"Une organisation sans relation entre structure et fonction","correct":false}]'::jsonb,5,'NIH/NCI SEER — Anatomy & Physiology',909,'source_validated',true,'clinical_case','[]'::jsonb,null,'{"source_url":"https://training.seer.cancer.gov/anatomy/","source_validation":"institutional_validated"}'::jsonb),
('10000002-71a0-4d01-9013-000000000001'::uuid,'78c516b6-2d5d-4979-b9f9-22e2653a37e1'::uuid,'Qu’est-ce qu’un allèle ?','Un allèle est une version d’une séquence d’ADN à un locus donné.','[{"text":"Une version d’une séquence d’ADN à un locus","correct":true},{"text":"Un type de cellule sanguine","correct":false},{"text":"Une hormone","correct":false},{"text":"Une membrane biologique","correct":false}]'::jsonb,1,'NHGRI — Allele',901,'source_validated',true,'mcq','[]'::jsonb,null,'{"source_url":"https://www.genome.gov/genetics-glossary/Allele","source_validation":"institutional_validated"}'::jsonb),
('10000002-71a0-4d01-9013-000000000002'::uuid,'78c516b6-2d5d-4979-b9f9-22e2653a37e1'::uuid,'Que signifie être homozygote pour un locus ?','Un individu homozygote possède deux versions identiques de l’allèle à ce locus.','[{"text":"Posséder deux allèles identiques","correct":true},{"text":"Posséder deux allèles différents","correct":false},{"text":"Ne posséder aucun chromosome","correct":false},{"text":"Posséder trois copies du même chromosome","correct":false}]'::jsonb,1,'NHGRI — Homozygous',902,'source_validated',true,'mcq','[]'::jsonb,null,'{"source_url":"https://www.genome.gov/genetics-glossary/homozygous","source_validation":"institutional_validated"}'::jsonb),
('10000002-71a0-4d01-9013-000000000003'::uuid,'78c516b6-2d5d-4979-b9f9-22e2653a37e1'::uuid,'Que signifie être hétérozygote pour un locus ?','Un individu hétérozygote possède deux allèles différents à ce locus.','[{"text":"Posséder deux allèles différents","correct":true},{"text":"Posséder deux allèles identiques","correct":false},{"text":"Ne posséder qu’un seul chromosome au total","correct":false},{"text":"Avoir deux cellules différentes","correct":false}]'::jsonb,2,'NHGRI — Allele',903,'source_validated',true,'mcq','[]'::jsonb,null,'{"source_url":"https://www.genome.gov/genetics-glossary/Allele","source_validation":"institutional_validated"}'::jsonb),
('10000002-71a0-4d01-9013-000000000004'::uuid,'78c516b6-2d5d-4979-b9f9-22e2653a37e1'::uuid,'Dans une transmission autosomique récessive, combien de copies altérées sont généralement nécessaires pour que la maladie s’exprime ?','Une maladie autosomique récessive nécessite habituellement deux copies altérées du gène, une héritée de chaque parent.','[{"text":"Deux copies altérées","correct":true},{"text":"Une seule copie dans tous les cas","correct":false},{"text":"Trois copies","correct":false},{"text":"Aucune copie","correct":false}]'::jsonb,2,'MedlinePlus Genetics — Inheritance patterns',904,'source_validated',true,'mcq','[]'::jsonb,null,'{"source_url":"https://medlineplus.gov/genetics/understanding/inheritance/inheritancepatterns/","source_validation":"institutional_validated"}'::jsonb),
('10000002-71a0-4d01-9013-000000000005'::uuid,'78c516b6-2d5d-4979-b9f9-22e2653a37e1'::uuid,'Qu’appelle-t-on généralement un porteur sain dans une maladie autosomique récessive ?','Il s’agit d’une personne possédant une copie altérée et une copie non altérée, généralement sans symptômes de la maladie.','[{"text":"Une personne ayant une seule copie altérée sans maladie manifeste","correct":true},{"text":"Une personne sans aucun allèle du gène","correct":false},{"text":"Une personne ayant toujours deux copies altérées","correct":false},{"text":"Une personne dépourvue de chromosomes","correct":false}]'::jsonb,2,'MedlinePlus Genetics — Inheritance patterns',905,'source_validated',true,'mcq','[]'::jsonb,null,'{"source_url":"https://medlineplus.gov/genetics/understanding/inheritance/inheritancepatterns/","source_validation":"institutional_validated"}'::jsonb),
('10000002-71a0-4d01-9013-000000000006'::uuid,'78c516b6-2d5d-4979-b9f9-22e2653a37e1'::uuid,'Que décrit le principe mendélien de ségrégation ?','Les deux allèles d’un locus se séparent lors de la formation des gamètes, de sorte que chaque gamète n’en reçoit qu’un.','[{"text":"Les deux allèles se séparent lors de la formation des gamètes","correct":true},{"text":"Les deux allèles restent toujours ensemble dans le même gamète","correct":false},{"text":"Les chromosomes disparaissent avant la reproduction","correct":false},{"text":"Chaque gamète reçoit deux copies de chaque allèle","correct":false}]'::jsonb,3,'NHGRI — Mendel segregation',906,'source_validated',true,'mcq','[]'::jsonb,null,'{"source_url":"https://www.genome.gov/Pages/Education/Modules/BasicsPresentation_vs2.pdf","source_validation":"institutional_validated"}'::jsonb),
('10000002-71a0-4d01-9013-000000000007'::uuid,'78c516b6-2d5d-4979-b9f9-22e2653a37e1'::uuid,'Quelle particularité caractérise une transmission liée au chromosome X ?','Un père transmet son chromosome Y à ses fils ; il ne peut donc pas transmettre directement un caractère lié à son chromosome X à un fils.','[{"text":"Il n’y a pas de transmission père-fils d’un caractère lié à l’X","correct":true},{"text":"Un père transmet toujours son chromosome X à ses fils","correct":false},{"text":"Les filles ne reçoivent jamais de chromosome X paternel","correct":false},{"text":"Le chromosome X n’intervient jamais dans l’hérédité","correct":false}]'::jsonb,3,'MedlinePlus Genetics — Inheritance patterns',907,'source_validated',true,'mcq','[]'::jsonb,null,'{"source_url":"https://medlineplus.gov/genetics/understanding/inheritance/inheritancepatterns/","source_validation":"institutional_validated"}'::jsonb),
('10000002-71a0-4d01-9013-000000000008'::uuid,'78c516b6-2d5d-4979-b9f9-22e2653a37e1'::uuid,'Cas d’application — Deux parents sont porteurs d’une même affection autosomique récessive. Quel mécanisme explique qu’un enfant puisse recevoir les deux allèles altérés ?','Chaque parent peut transmettre son allèle altéré dans un gamète ; l’enfant peut alors recevoir une copie altérée de chacun.','[{"text":"La ségrégation des allèles dans les gamètes des deux parents","correct":true},{"text":"La transmission de deux allèles par un seul gamète","correct":false},{"text":"L’absence complète de méiose","correct":false},{"text":"La disparition des chromosomes parentaux","correct":false}]'::jsonb,4,'NHGRI / MedlinePlus — Mendelian inheritance',908,'source_validated',true,'clinical_case','[]'::jsonb,null,'{"source_validation":"institutional_validated"}'::jsonb),
('10000002-71a0-4d01-9013-000000000009'::uuid,'78c516b6-2d5d-4979-b9f9-22e2653a37e1'::uuid,'Quel raisonnement résume le mieux l’hérédité mendélienne simple ?','Un individu reçoit des allèles de ses parents ; leur combinaison et leur mode dominant ou récessif influencent l’expression du caractère.','[{"text":"Transmission d’allèles parentaux avec expression selon leur mode d’hérédité","correct":true},{"text":"Transmission indépendante de l’ADN","correct":false},{"text":"Expression toujours identique quel que soit le génotype","correct":false},{"text":"Absence de séparation des allèles lors de la formation des gamètes","correct":false}]'::jsonb,5,'NHGRI — Mendelian Inheritance',909,'source_validated',true,'clinical_case','[]'::jsonb,null,'{"source_url":"https://www.genome.gov/genetics-glossary/Mendelian-Inheritance","source_validation":"institutional_validated"}'::jsonb),
('10000001-71a0-4d01-9013-000000000001'::uuid,'de38cb27-c7c0-4b6b-8036-5b2e6dcfbde4'::uuid,'Où se trouve la majeure partie de l’ADN d’une cellule humaine ?','La majeure partie de l’ADN humain est située dans le noyau ; une petite quantité se trouve aussi dans les mitochondries.','[{"text":"Dans le noyau","correct":true},{"text":"Dans les lysosomes uniquement","correct":false},{"text":"Dans le plasma sanguin uniquement","correct":false},{"text":"Dans la paroi cellulaire","correct":false}]'::jsonb,1,'MedlinePlus Genetics — What is DNA?',901,'source_validated',true,'mcq','[]'::jsonb,null,'{"source_url":"https://medlineplus.gov/genetics/understanding/basics/dna/","source_validation":"institutional_validated"}'::jsonb),
('10000001-71a0-4d01-9013-000000000002'::uuid,'de38cb27-c7c0-4b6b-8036-5b2e6dcfbde4'::uuid,'Qu’est-ce qu’un gène ?','Un gène est une unité physique et fonctionnelle d’hérédité constituée d’ADN.','[{"text":"Une séquence d’ADN ayant une fonction biologique","correct":true},{"text":"Un type de globule rouge","correct":false},{"text":"Une hormone","correct":false},{"text":"Une membrane cellulaire","correct":false}]'::jsonb,1,'MedlinePlus Genetics — What is a gene?',902,'source_validated',true,'mcq','[]'::jsonb,null,'{"source_url":"https://medlineplus.gov/genetics/understanding/basics/gene/","source_validation":"institutional_validated"}'::jsonb),
('10000001-71a0-4d01-9013-000000000003'::uuid,'de38cb27-c7c0-4b6b-8036-5b2e6dcfbde4'::uuid,'Qu’est-ce qu’un chromosome ?','Un chromosome est une structure constituée d’une longue molécule d’ADN associée à des protéines.','[{"text":"Une structure d’ADN associée à des protéines","correct":true},{"text":"Une enzyme digestive","correct":false},{"text":"Une cellule sanguine","correct":false},{"text":"Un neurotransmetteur","correct":false}]'::jsonb,2,'MedlinePlus Genetics — What is a chromosome?',903,'source_validated',true,'mcq','[]'::jsonb,null,'{"source_url":"https://medlineplus.gov/genetics/understanding/basics/chromosome/","source_validation":"institutional_validated"}'::jsonb),
('10000001-71a0-4d01-9013-000000000004'::uuid,'de38cb27-c7c0-4b6b-8036-5b2e6dcfbde4'::uuid,'Pourquoi l’ADN doit-il être répliqué avant une division cellulaire ?','L’ADN est copié afin que chaque cellule fille reçoive un génome complet.','[{"text":"Pour que chaque cellule fille reçoive une copie du génome","correct":true},{"text":"Pour transformer l’ADN en glucose","correct":false},{"text":"Pour supprimer tous les chromosomes","correct":false},{"text":"Pour produire directement des lipides","correct":false}]'::jsonb,2,'NHGRI — DNA Replication',904,'source_validated',true,'mcq','[]'::jsonb,null,'{"source_url":"https://www.genome.gov/genetics-glossary/DNA-Replication","source_validation":"institutional_validated"}'::jsonb),
('10000001-71a0-4d01-9013-000000000005'::uuid,'de38cb27-c7c0-4b6b-8036-5b2e6dcfbde4'::uuid,'Que produit la transcription d’un gène codant ?','La transcription utilise l’ADN comme modèle pour fabriquer une molécule d’ARN, notamment un ARN messager.','[{"text":"Une copie ARN de la séquence d’ADN","correct":true},{"text":"Une protéine directement","correct":false},{"text":"Un chromosome supplémentaire","correct":false},{"text":"Un acide gras","correct":false}]'::jsonb,2,'NHGRI — Transcription',905,'source_validated',true,'mcq','[]'::jsonb,null,'{"source_url":"https://www.genome.gov/genetics-glossary/Transcription","source_validation":"institutional_validated"}'::jsonb),
('10000001-71a0-4d01-9013-000000000006'::uuid,'de38cb27-c7c0-4b6b-8036-5b2e6dcfbde4'::uuid,'Quel est le rôle principal de l’ARN messager ?','L’ARN messager transporte l’information nécessaire à la synthèse d’une protéine depuis l’ADN vers la machinerie de traduction.','[{"text":"Transporter l’information nécessaire à la synthèse protéique","correct":true},{"text":"Stocker tout le génome à long terme","correct":false},{"text":"Former la membrane cellulaire","correct":false},{"text":"Dégrader tous les chromosomes","correct":false}]'::jsonb,3,'NHGRI — RNA / mRNA',906,'source_validated',true,'mcq','[]'::jsonb,null,'{"source_url":"https://www.genome.gov/about-genomics/educational-resources/fact-sheets/ribonucleic-acid-fact-sheet","source_validation":"institutional_validated"}'::jsonb),
('10000001-71a0-4d01-9013-000000000007'::uuid,'de38cb27-c7c0-4b6b-8036-5b2e6dcfbde4'::uuid,'Que se passe-t-il lors de la traduction ?','Le ribosome lit les codons de l’ARN messager et assemble les acides aminés d’une protéine.','[{"text":"Le ribosome assemble des acides aminés à partir du message ARN","correct":true},{"text":"L’ADN est recopié en ADN","correct":false},{"text":"Le noyau fabrique des globules rouges","correct":false},{"text":"Le glucose est transformé en ADN","correct":false}]'::jsonb,3,'NHGRI — Transcription and Translation',907,'source_validated',true,'mcq','[]'::jsonb,null,'{"source_url":"https://www.genome.gov/about-genomics/teaching-tools/Transcription-Translation","source_validation":"institutional_validated"}'::jsonb),
('10000001-71a0-4d01-9013-000000000008'::uuid,'de38cb27-c7c0-4b6b-8036-5b2e6dcfbde4'::uuid,'Cas d’application — Une mutation empêche la transcription d’un gène. Quel produit immédiat risque de manquer ?','Si la transcription est bloquée, la copie ARN du gène ne peut pas être produite normalement.','[{"text":"L’ARN issu de ce gène","correct":true},{"text":"Le calcium sanguin","correct":false},{"text":"La bile","correct":false},{"text":"Les plaquettes","correct":false}]'::jsonb,4,'NHGRI — Transcription',908,'source_validated',true,'clinical_case','[]'::jsonb,null,'{"source_url":"https://www.genome.gov/genetics-glossary/Transcription","source_validation":"institutional_validated"}'::jsonb),
('10000001-71a0-4d01-9013-000000000009'::uuid,'de38cb27-c7c0-4b6b-8036-5b2e6dcfbde4'::uuid,'Quel enchaînement résume correctement l’expression d’un gène codant une protéine ?','L’information de l’ADN est d’abord transcrite en ARN messager, puis cet ARN est traduit en protéine.','[{"text":"ADN → ARN messager → protéine","correct":true},{"text":"Protéine → ADN → ARN","correct":false},{"text":"ARN → glucose → ADN","correct":false},{"text":"ADN → lipide → ARN","correct":false}]'::jsonb,5,'NHGRI — Transcription and Translation',909,'source_validated',true,'clinical_case','[]'::jsonb,null,'{"source_url":"https://www.genome.gov/about-genomics/teaching-tools/Transcription-Translation","source_validation":"institutional_validated"}'::jsonb)
