-- IFSI validated external sources batch 4
-- DNA/RNA, Mendelian inheritance, General anatomy
-- Sources: NHGRI, MedlinePlus Genetics, NIH/NCI SEER Training

update public.curriculum_lessons set content='L’anatomie étudie la structure du corps humain. Le corps est organisé selon plusieurs niveaux : cellules, tissus, organes puis systèmes. Une cellule constitue une unité de base du vivant ; plusieurs cellules organisées peuvent former un tissu. Un organe associe plusieurs types de tissus qui coopèrent pour assurer une fonction particulière. Un système regroupe plusieurs organes qui travaillent ensemble pour réaliser des fonctions complexes. Les grands systèmes comprennent notamment les systèmes squelettique, musculaire, nerveux, endocrinien, cardiovasculaire, lymphatique, respiratoire, digestif, urinaire et reproducteur. La description anatomique utilise des termes directionnels, des plans de référence et des cavités corporelles. Le maintien de l’homéostasie correspond à la conservation relative d’un environnement interne stable malgré les variations.',source_files='[{"label":"Support « COURS ANATOMIE IFSI »."},{"url":"https://medlineplus.gov/anatomy.html","label":"MedlinePlus — Anatomy","validation":"institutional_validated"},{"url":"https://training.seer.cancer.gov/anatomy/","label":"NIH/NCI SEER Training — Anatomy & Physiology","validation":"institutional_validated"},{"url":"https://training.seer.cancer.gov/anatomy/body/review.html","label":"NIH/NCI SEER Training — Introduction to the Human Body","validation":"institutional_validated"}]'::jsonb,updated_at=now() where id='5f328b13-1ebd-463d-860e-4aae6699528a'::uuid;
update public.curriculum_lessons set content='L’hérédité correspond à la transmission de caractéristiques génétiques des parents aux descendants. Un allèle est une version d’une séquence d’ADN à un locus donné ; pour un locus autosomique, un individu hérite généralement d’un allèle de chaque parent. Deux allèles identiques correspondent à un état homozygote, tandis que deux allèles différents correspondent à un état hétérozygote. Dans une transmission autosomique dominante, une seule copie altérée d’un gène peut suffire à produire le caractère ou la maladie. Dans une transmission autosomique récessive, deux copies altérées sont généralement nécessaires ; une personne ne possédant qu’une copie altérée peut être porteuse sans être malade. Les transmissions liées au chromosome X ont des particularités propres, notamment l’absence de transmission père-fils pour un caractère lié à l’X. La ségrégation mendélienne décrit le fait que les deux allèles d’un locus se séparent lors de la formation des gamètes, de sorte qu’un gamète n’en reçoit qu’un.',source_files='[{"label":"Support sur l’hérédité et les lois de Mendel."},{"url":"https://www.genome.gov/genetics-glossary/Mendelian-Inheritance","label":"NHGRI — Mendelian Inheritance","validation":"institutional_validated"},{"url":"https://www.genome.gov/genetics-glossary/Allele","label":"NHGRI — Allele","validation":"institutional_validated"},{"url":"https://medlineplus.gov/genetics/understanding/inheritance/inheritancepatterns/","label":"MedlinePlus Genetics — Inheritance patterns","validation":"institutional_validated"},{"url":"https://www.genome.gov/Pages/Education/Modules/BasicsPresentation_vs2.pdf","label":"NHGRI — Basics Presentation / Mendel segregation","validation":"institutional_validated"}]'::jsonb,updated_at=now() where id='e6b3c491-7e48-41da-9de9-4e2dda6d2a3a'::uuid;
update public.curriculum_lessons set content='L’ADN (acide désoxyribonucléique) constitue le principal support de l’information génétique. Chez l’être humain, il est principalement situé dans le noyau, avec une petite quantité d’ADN mitochondrial. L’ADN est formé de nucléotides contenant quatre bases : adénine (A), thymine (T), cytosine (C) et guanine (G), organisées en double hélice. Un gène est une unité fonctionnelle d’hérédité constituée d’ADN. Les chromosomes correspondent à de longues molécules d’ADN associées à des protéines. Avant une division cellulaire, l’ADN est répliqué afin que chaque cellule fille reçoive une copie complète du génome. Lors de la transcription, une séquence d’ADN sert de modèle pour fabriquer un ARN, notamment un ARN messager. Lors de la traduction, le ribosome lit les codons de l’ARN messager et assemble une chaîne d’acides aminés qui formera une protéine.',source_files='[{"label":"Support ADN-ARN + lexique de génétique."},{"url":"https://www.genome.gov/about-genomics/fact-sheets/Deoxyribonucleic-Acid-Fact-Sheet","label":"NHGRI — DNA Fact Sheet","validation":"institutional_validated"},{"url":"https://www.genome.gov/about-genomics/educational-resources/fact-sheets/ribonucleic-acid-fact-sheet","label":"NHGRI — RNA Fact Sheet","validation":"institutional_validated"},{"url":"https://www.genome.gov/about-genomics/teaching-tools/Transcription-Translation","label":"NHGRI — Transcription and Translation","validation":"institutional_validated"},{"url":"https://www.genome.gov/genetics-glossary/DNA-Replication","label":"NHGRI — DNA Replication","validation":"institutional_validated"}]'::jsonb,updated_at=now() where id='e9ef02e6-d8f3-4046-8034-eac3a1e0d4b1'::uuid;

update public.curriculum_quiz_questions set question_text='Que désigne l’anatomie ?',explanation='L’anatomie est la science qui étudie la structure du corps.',options='[{"text":"L’étude de la structure du corps","correct":true},{"text":"L’étude exclusive des médicaments","correct":false},{"text":"L’étude exclusive des microbes","correct":false},{"text":"L’étude exclusive du comportement","correct":false}]'::jsonb,difficulty=1,source_label='MedlinePlus — Anatomy',display_order=900,validation_status='source_validated',is_published=true,question_type='mcq',metadata='{"source_url":"https://medlineplus.gov/anatomy.html","minimum_10_batch":"v4","source_validation":"institutional_validated"}'::jsonb where id='1624df90-50f7-4997-8045-c35359450409'::uuid;
update public.curriculum_quiz_questions set question_text='Dans une transmission autosomique dominante, combien de copies altérées d’un gène peuvent suffire à produire le caractère ?',explanation='Dans une transmission autosomique dominante, une seule copie altérée peut suffire.',options='[{"text":"Une seule copie","correct":true},{"text":"Deux copies obligatoirement","correct":false},{"text":"Trois copies","correct":false},{"text":"Aucune copie","correct":false}]'::jsonb,difficulty=1,source_label='MedlinePlus Genetics — Inheritance patterns',display_order=900,validation_status='source_validated',is_published=true,question_type='mcq',metadata='{"source_url":"https://medlineplus.gov/genetics/understanding/inheritance/inheritancepatterns/","minimum_10_batch":"v4","source_validation":"institutional_validated"}'::jsonb where id='8fe9d387-ed83-49d6-8d69-c57f8ec269c5'::uuid;
update public.curriculum_quiz_questions set question_text='Quelles sont les quatre bases de l’ADN ?',explanation='L’ADN utilise quatre bases : adénine, thymine, cytosine et guanine.',options='[{"text":"Adénine, thymine, cytosine et guanine","correct":true},{"text":"Adénine, uracile, cytosine et guanine","correct":false},{"text":"Adénine, thymine, uracile et glucose","correct":false},{"text":"Thymine, ribose, cytosine et phosphate","correct":false}]'::jsonb,difficulty=1,source_label='NHGRI — DNA Fact Sheet',display_order=900,validation_status='source_validated',is_published=true,question_type='mcq',metadata='{"source_url":"https://www.genome.gov/about-genomics/fact-sheets/Deoxyribonucleic-Acid-Fact-Sheet","minimum_10_batch":"v4","source_validation":"institutional_validated"}'::jsonb where id='fca2c4e0-428b-41de-b075-4ba164e0de0d'::uuid;

